command:
/**
 * CLICK MACRO TO INCREASE DIE SIZE.
 * SHIFT + CLICK TO RESET BACK TO BASE.
 */
let hero = game.user.character;
if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled.find(t => t.actor?.getFlag("vagabond-app", "fisticuffs"))?.actor;
}

if (!hero || !hero.getFlag("vagabond-app", "fisticuffs")) return;

const name = hero.system.parent.name;
const fisticuffs = hero.effects.find(fx => fx.name.toUpperCase() === "FISTICUFFS");
const brawlBonus = {
  key: "system.modifiers.damage.out.brawl.dice.size.bonus",
  type: "add",
  mode: 2,
  value: 2,
  priority: 20
}

if (event.shiftKey) {
  token.actor.deleteEmbeddedDocuments("ActiveEffect", [fisticuffs.id]);
}
else if (!fisticuffs) {
  const effectData = {
    name: "Fisticuffs",
    img: "/icons/skills/melee/unarmed-punch-fist-yellow-red.webp",
    showIcon: 2,
    changes: [{...brawlBonus}]
  }
  await token.actor.createEmbeddedDocuments("ActiveEffect", [effectData]);
}
else {
  await fisticuffs.update({ changes: [...fisticuffs.changes, {...brawlBonus}]})
}
